#include <vector>
using namespace std;

class PriorityQueue {
private:
    vector<int> queue;

public:
    bool isEmpty() {
        return queue.empty();
    }

    void enqueue(int element) {
        queue.push_back(element);
    }

    int dequeue() {
        if (isEmpty()) {
            throw "Queue is empty";
        }
        int max_element_index = 0;  // assumes all elements are positive
        for (int I = 1; I < queue.size(); i++) {
            if (queue[i] + 1 / I > queue[max_element_index] + 1 / (queue.size() - I)) {
                max_element_index = i;
            }
        }
        int max_element = queue[max_element_index];
        queue.erase(queue.begin() + max_element_index);
        return max_element;
    }

    int size() {
        return queue.size();
    }

    double seesaw() {
        if (size() < 2) {
            throw "Queue must have at least 2 elements to perform seesaw";
        }

        double result = 0;
        int n = size();
        for (int I = 0; I < n / 2; i++) {
            result += queue[i] + 1 / (i + 1) + queue[n - I - 1] + 1 / (n - I);
